/**
 * Job title neighbour map: every role (an occupation from a public classification, or a title
 * learned from Velai's own postings) with its names, and weighted links to the roles next to it.
 * The map is a graph; a tree is read out of it from any title (`neighbourTree`).
 *
 * Generated by scripts/build-title-map.ts (data/title-map.json); this module is the pure read side.
 * Names are normalised with `normalizeTitleName`, the same rule the title alias graph uses.
 */
import { normalizeTitleName, type TitleSourceMeta } from "./title-aliases";

/**
 * Why two roles are linked.
 *  e = expert-reviewed related occupation (O*NET Related Occupations)
 *  s = they ask for the same skills (ESCO essential and optional skills, IDF-weighted cosine)
 *  x = official ESCO to O*NET-SOC crosswalk (the same work in the two classifications)
 *  p = their postings ask for the same things (learned from Velai's index)
 *  n = they share a title
 */
export type TitleMapLinkKind = "e" | "s" | "x" | "p" | "n";

export interface TitleMapRole {
  /** `esco:<uuid>`, `onet:<O*NET-SOC code>` or `postings:<normalised title>`. */
  id: string;
  /** Display title. */
  label: string;
  /** Key into `groups` (an ISCO-08 unit group, a SOC major group); absent when unknown. */
  group?: string;
  /** Normalised names, label first. */
  names: string[];
}

export interface TitleMap {
  sources: TitleSourceMeta[];
  /** Group key -> label; a key's parent is its prefix one level up (`isco:1223` -> `isco:122`), when present. */
  groups: Record<string, string>;
  roles: TitleMapRole[];
  /** [from role index, to role index, weight 1-100, kind]; stored once per pair, read both ways. */
  links: Array<[number, number, number, TitleMapLinkKind]>;
}

export interface TitleNeighbour {
  role: TitleMapRole;
  /** 0-1. */
  weight: number;
  kinds: TitleMapLinkKind[];
}

export interface TitleTreeNode {
  role: TitleMapRole;
  weight: number;
  kinds: TitleMapLinkKind[];
  children: TitleTreeNode[];
}

interface MapIndex {
  byName: Map<string, number[]>;
  byId: Map<string, number>;
  /** Per role: neighbour index -> [weight, kinds], the strongest link per kind kept. */
  adjacency: Array<Map<number, { weight: number; kinds: Set<TitleMapLinkKind> }>>;
}

const indexes = new WeakMap<TitleMap, MapIndex>();

/**
 * Two roles linked by several sources are closer than either source says alone: the combined
 * weight is 1 - prod(1 - w) (a noisy-or), so agreement raises the link and never lowers it.
 */
export function combineWeights(weights: number[]): number {
  return 1 - weights.reduce((rest, w) => rest * (1 - Math.min(Math.max(w, 0), 1)), 1);
}

function indexOf(map: TitleMap): MapIndex {
  let index = indexes.get(map);
  if (index) return index;
  const byName = new Map<string, number[]>();
  const byId = new Map<string, number>();
  map.roles.forEach((role, i) => {
    byId.set(role.id, i);
    for (const name of role.names) {
      const list = byName.get(name);
      if (list) list.push(i);
      else byName.set(name, [i]);
    }
  });
  const perKind: Array<Map<number, Map<TitleMapLinkKind, number>>> = map.roles.map(() => new Map());
  const add = (a: number, b: number, w: number, kind: TitleMapLinkKind) => {
    const kinds = perKind[a].get(b) ?? new Map<TitleMapLinkKind, number>();
    kinds.set(kind, Math.max(kinds.get(kind) ?? 0, w));
    perKind[a].set(b, kinds);
  };
  for (const [a, b, w, kind] of map.links) {
    if (a === b || !map.roles[a] || !map.roles[b]) continue;
    add(a, b, w / 100, kind);
    add(b, a, w / 100, kind);
  }
  const adjacency = perKind.map((row) => {
    const out = new Map<number, { weight: number; kinds: Set<TitleMapLinkKind> }>();
    for (const [j, kinds] of row) out.set(j, { weight: combineWeights([...kinds.values()]), kinds: new Set(kinds.keys()) });
    return out;
  });
  index = { byName, byId, adjacency };
  indexes.set(map, index);
  return index;
}

/** Roles that hold this title as one of their names (several when sources disagree on what it is). */
export function rolesForTitle(map: TitleMap, title: string): TitleMapRole[] {
  return (indexOf(map).byName.get(normalizeTitleName(title)) ?? []).map((i) => map.roles[i]);
}

/**
 * The roles a title IS: those whose display title it is. Only when none is, every role that lists it
 * among its names. A role that merely lists the title (O*NET's Marketing Managers lists "Product
 * Manager" among 60 reported titles) is then one step away, through the shared-title link, not the root.
 */
export function ownRoles(map: TitleMap, title: string): TitleMapRole[] {
  const key = normalizeTitleName(title);
  const holders = rolesForTitle(map, title);
  const named = holders.filter((r) => normalizeTitleName(r.label) === key);
  return named.length > 0 ? named : holders;
}

function roleIndex(map: TitleMap, id: string): number {
  return indexOf(map).byId.get(id) ?? -1;
}

const KIND_ORDER: TitleMapLinkKind[] = ["n", "x", "e", "p", "s"];
const byKindOrder = (a: TitleMapLinkKind, b: TitleMapLinkKind) => KIND_ORDER.indexOf(a) - KIND_ORDER.indexOf(b);

/** Neighbours of one role, strongest first; ties broken by label so the order is stable. */
export function roleNeighbours(map: TitleMap, roleId: string, limit = 10, minWeight = 0): TitleNeighbour[] {
  const i = roleIndex(map, roleId);
  if (i < 0) return [];
  return [...indexOf(map).adjacency[i]]
    .filter(([, l]) => l.weight >= minWeight)
    .sort(([ja, a], [jb, b]) => b.weight - a.weight || map.roles[ja].label.localeCompare(map.roles[jb].label))
    .slice(0, limit)
    .map(([j, l]) => ({ role: map.roles[j], weight: l.weight, kinds: [...l.kinds].sort(byKindOrder) }));
}

/**
 * The tree read from one title: its roles at the top, each role's strongest neighbours below it,
 * and theirs below them, to `depth` levels. A role appears once, at its first (shallowest,
 * strongest) place, so the tree never loops back to where it started.
 */
export function neighbourTree(
  map: TitleMap,
  title: string,
  opts: { depth?: number; breadth?: number; minWeight?: number } = {},
): TitleTreeNode[] {
  const { depth = 2, breadth = 6, minWeight = 0.2 } = opts;
  const roots = ownRoles(map, title);
  const seen = new Set(roots.map((r) => r.id));
  const nodes: TitleTreeNode[] = roots.map((role) => ({ role, weight: 1, kinds: [], children: [] }));
  let frontier = nodes;
  for (let level = 0; level < depth; level++) {
    const next: TitleTreeNode[] = [];
    for (const node of frontier) {
      for (const n of roleNeighbours(map, node.role.id, breadth * 3, minWeight)) {
        if (node.children.length >= breadth) break;
        if (seen.has(n.role.id)) continue;
        seen.add(n.role.id);
        const child: TitleTreeNode = { role: n.role, weight: n.weight, kinds: n.kinds, children: [] };
        node.children.push(child);
        next.push(child);
      }
    }
    frontier = next;
  }
  return nodes;
}

/**
 * Titles of the roles next to a title, strongest first: other jobs to search for. A role linked only
 * because it shares the title (kind `n`) is the same job in another classification, so it is left out.
 */
export function neighbourTitles(map: TitleMap, title: string, limit = 8, minWeight = 0.3): string[] {
  const roots = ownRoles(map, title);
  const own = new Set(roots.flatMap((r) => r.names));
  const best = new Map<string, number>();
  for (const role of roots) {
    for (const n of roleNeighbours(map, role.id, limit * 3, minWeight)) {
      const key = normalizeTitleName(n.role.label);
      if (own.has(key) || n.kinds.every((k) => k === "n")) continue;
      best.set(n.role.label, Math.max(best.get(n.role.label) ?? 0, n.weight));
    }
  }
  return [...best].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, limit).map(([label]) => label);
}
